type TarefaLida = ListTarefaOutput['items'][number];

interface Derivados {
  aberta: boolean;
  venceHoje: boolean;
  atrasada: boolean;
  devolvidaPendente: boolean;
  quemAgeAgora: string | null;
  prazo: string | null;
}

interface Ambiente {
  hoje: string;
  listas: Map<string, string>;
  nomes: Map<string, string>;
}

function paraStatus(valor: string): Status {
  switch (valor) {
    case 'aFazer':
    case 'emAndamento':
    case 'emRevisao':
    case 'concluida':
    case 'cancelada':
      return valor;
    default:
      throw new AppError('INVALID_DATA', 'Situação de tarefa desconhecida: ' + valor, 500);
  }
}

function paraPrioridade(valor: string): Prioridade {
  switch (valor) {
    case 'baixa':
    case 'media':
    case 'alta':
      return valor;
    default:
      throw new AppError('INVALID_DATA', 'Prioridade de tarefa desconhecida: ' + valor, 500);
  }
}

function hojeDe(ctx: RequestContext): string {
  const d = new Date(ctx.clock.nowIso());
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: ctx.organization.timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(d);
}

function pessoaDaSessao(ctx: RequestContext): string {
  const id = ctx.sessionContext.actorId;
  if (id == null || id === '') {
    throw new AppError('UNAUTHENTICATED', 'Pessoa da sessão não identificada', 401);
  }
  return id;
}

function derivar(t: TarefaLida, hoje: string): Derivados {
  const status = paraStatus(String(t.status));
  // tarefaAbertaVencimento: aberta = nem concluída nem cancelada; vence hoje = prazo igual a hoje; atrasada = prazo anterior a hoje
  const aberta = status !== 'concluida' && status !== 'cancelada';
  const prazo = t.prazo == null || t.prazo === '' ? null : String(t.prazo).slice(0, 10);
  const venceHoje = aberta && prazo != null && prazo === hoje;
  const atrasada = aberta && prazo != null && prazo < hoje;
  // quemAgeAgoraPorSituacao: responsável (a fazer / em andamento), quem criou (em revisão), ninguém (concluída / cancelada)
  let quemAgeAgora: string | null = null;
  if (status === 'aFazer' || status === 'emAndamento') quemAgeAgora = t.responsavelId;
  else if (status === 'emRevisao') quemAgeAgora = t.criadorId;
  const devolvidaEm = t.details.devolvidaEm;
  const retomadaEm = t.details.retomadaEm;
  const devolvidaPendente =
    status === 'emAndamento' &&
    devolvidaEm != null &&
    (retomadaEm == null || String(retomadaEm) < String(devolvidaEm));
  return { aberta, venceHoje, atrasada, devolvidaPendente, quemAgeAgora, prazo };
}

async function listarTodasTarefasPor(
  campo: 'responsavelId' | 'criadorId',
  pessoaId: string,
  ctx: RequestContext,
): Promise<TarefaLida[]> {
  const todas: TarefaLida[] = [];
  let page = 1;
  for (;;) {
    const r =
      campo === 'responsavelId'
        ? await listTarefa({ responsavelId: pessoaId, page, pageSize: 200 }, ctx)
        : await listTarefa({ criadorId: pessoaId, page, pageSize: 200 }, ctx);
    todas.push(...r.items);
    if (!r.hasMore) break;
    page += 1;
  }
  return todas;
}

async function carregarTarefa(id: string, ctx: RequestContext): Promise<TarefaLida> {
  const r = await listTarefa({ id, page: 1, pageSize: 1 }, ctx);
  const t = r.items[0];
  if (t == null) {
    throw new AppError('NOT_FOUND', 'Tarefa não encontrada', 404, { id });
  }
  return t;
}

async function carregarListas(ctx: RequestContext): Promise<Map<string, string>> {
  const mapa = new Map<string, string>();
  let page = 1;
  for (;;) {
    const r = await listListaTarefas({ page, pageSize: 200 }, ctx);
    for (const l of r.items) mapa.set(l.id, l.nome);
    if (!r.hasMore) break;
    page += 1;
  }
  return mapa;
}

async function nomeParticipante(id: string, amb: Ambiente, ctx: RequestContext): Promise<string> {
  const guardado = amb.nomes.get(id);
  if (guardado != null) return guardado;
  const p = await getParticipante({ id }, ctx);
  const nome = p.details.identification.name;
  amb.nomes.set(id, nome);
  return nome;
}

async function progressoChecklist(tarefaId: string, ctx: RequestContext): Promise<string> {
  let total = 0;
  let marcados = 0;
  let page = 1;
  for (;;) {
    const r = await listItemChecklist({ tarefaId, page, pageSize: 200 }, ctx);
    for (const item of r.items) {
      total += 1;
      if (item.details.concluido === true) marcados += 1;
    }
    if (!r.hasMore) break;
    page += 1;
  }
  return `${marcados} de ${total}`;
}

async function criarAmbiente(ctx: RequestContext): Promise<Ambiente> {
  return { hoje: hojeDe(ctx), listas: await carregarListas(ctx), nomes: new Map<string, string>() };
}

async function montarPendencia(t: TarefaLida, amb: Ambiente, ctx: RequestContext): Promise<PendenciaTarefaOut> {
  const d = derivar(t, amb.hoje);
  const nomeLista = amb.listas.get(t.listaId);
  if (nomeLista == null) {
    throw new AppError('NOT_FOUND', 'Lista de tarefas da tarefa "' + t.titulo + '" não encontrada', 404, {
      listaId: t.listaId,
      tarefaId: t.id,
    });
  }
  const nomeResponsavel = await nomeParticipante(t.responsavelId, amb, ctx);
  const nomeCriador = await nomeParticipante(t.criadorId, amb, ctx);
  const progresso = await progressoChecklist(t.id, ctx);
  const detalhes: PendenciaTarefaOut['details'] = {
    ...(d.quemAgeAgora != null ? { quemAgeAgora: d.quemAgeAgora } : {}),
    devolvidaPendente: d.devolvidaPendente,
    ...(t.details.motivoDevolucao != null ? { motivoDevolucao: t.details.motivoDevolucao } : {}),
    progressoChecklist: progresso,
    venceHoje: d.venceHoje,
    atrasada: d.atrasada,
  };
  const saida: PendenciaTarefaOut = {
    id: t.id,
    version: Number(t.version),
    titulo: t.titulo,
    status: paraStatus(String(t.status)),
    prioridade: paraPrioridade(String(t.prioridade)),
    listaId: t.listaId,
    responsavelId: t.responsavelId,
    criadorId: t.criadorId,
    criadaEm: t.criadaEm,
    details: detalhes,
    listaTarefas: { id: t.listaId, nome: nomeLista },
    responsavel: { id: t.responsavelId, details: { identification: { name: nomeResponsavel } } },
    criador: { id: t.criadorId, details: { identification: { name: nomeCriador } } },
  };
  if (d.prazo != null) saida.prazo = d.prazo;
  return saida;
}

function calcularIndicadores(tarefasDoResponsavel: TarefaLida[], hoje: string): IndicadoresOut {
  let abertas = 0;
  let vencemHoje = 0;
  let atrasadas = 0;
  let devolvidasPendentes = 0;
  for (const t of tarefasDoResponsavel) {
    const d = derivar(t, hoje);
    if (d.aberta) abertas += 1;
    if (d.venceHoje) vencemHoje += 1;
    if (d.atrasada) atrasadas += 1;
    if (d.devolvidaPendente) devolvidasPendentes += 1;
  }
  return { abertas, vencemHoje, atrasadas, devolvidasPendentes };
}

function comparar(a: TarefaLida, b: TarefaLida): number {
  const pa = a.prazo == null || a.prazo === '' ? null : String(a.prazo).slice(0, 10);
  const pb = b.prazo == null || b.prazo === '' ? null : String(b.prazo).slice(0, 10);
  if (pa !== pb) {
    if (pa == null) return 1;
    if (pb == null) return -1;
    return pa < pb ? -1 : 1;
  }
  if (a.criadaEm === b.criadaEm) return 0;
  return a.criadaEm < b.criadaEm ? -1 : 1;
}

interface ParametrosTransicao {
  id: string;
  version: number;
  transicao: TransicaoTarefa;
  ator: 'responsavel' | 'criador';
  ruleAtor: 'apenasResponsavelExecuta' | 'apenasCriadorRevisa';
  statusEsperado: Status;
  exigeDevolvida: boolean;
  exigeMotivo: boolean;
  motivoDevolucao?: string;
}

async function executarTransicao(ctx: RequestContext, p: ParametrosTransicao): Promise<SaidaComando> {
  return ctx.data.moduleData.runInTransaction(async (tx) => {
    const bound: RequestContext = { ...ctx, data: { ...ctx.data, moduleData: tx } };
    const pessoa = pessoaDaSessao(bound);
    const hoje = hojeDe(bound);
    const atual = await carregarTarefa(p.id, bound);
    const derAtual = derivar(atual, hoje);

    // apenasResponsavelExecuta / apenasCriadorRevisa
    const donoId = p.ator === 'responsavel' ? atual.responsavelId : atual.criadorId;
    if (donoId !== pessoa) {
      throw new AppError(
        'FORBIDDEN',
        p.ator === 'responsavel'
          ? 'Somente o responsável pode executar esta ação na tarefa "' + atual.titulo + '"'
          : 'Somente quem criou pode revisar a tarefa "' + atual.titulo + '"',
        403,
        { ruleId: p.ruleAtor, tarefaId: atual.id },
      );
    }
    if (paraStatus(String(atual.status)) !== p.statusEsperado) {
      throw new AppError(
        'INVALID_STATE',
        'A tarefa "' + atual.titulo + '" não está na situação necessária para esta ação',
        409,
        { ruleId: p.ruleAtor, tarefaId: atual.id, status: atual.status, esperado: p.statusEsperado },
      );
    }
    if (Number(atual.version) !== p.version) {
      throw new AppError(
        'VERSION_CONFLICT',
        'A tarefa "' + atual.titulo + '" foi alterada por outra pessoa; recarregue e tente de novo',
        409,
        { tarefaId: atual.id, versaoLida: p.version, versaoAtual: atual.version },
      );
    }
    // retomarSoAposDevolucao
    if (p.exigeDevolvida && !derAtual.devolvidaPendente) {
      throw new AppError(
        'INVALID_STATE',
        'A tarefa "' + atual.titulo + '" não está devolvida aguardando retomada',
        409,
        { ruleId: 'retomarSoAposDevolucao', tarefaId: atual.id },
      );
    }
    // devolucaoExigeMotivo
    const motivo = p.motivoDevolucao == null ? '' : p.motivoDevolucao.trim();
    if (p.exigeMotivo && motivo === '') {
      throw new AppError(
        'VALIDATION_ERROR',
        'Informe o motivo da devolução da tarefa "' + atual.titulo + '"',
        400,
        { ruleId: 'devolucaoExigeMotivo', tarefaId: atual.id },
      );
    }

    const resultado = p.exigeMotivo
      ? await avancarEtapaTarefa({ tarefaId: atual.id, transicao: p.transicao, motivoDevolucao: motivo }, bound)
      : await avancarEtapaTarefa({ tarefaId: atual.id, transicao: p.transicao }, bound);
    if (resultado.outcome !== 'applied') {
      throw new AppError(
        'CONFLICT',
        'A ação não pôde ser aplicada à tarefa "' + atual.titulo + '"',
        409,
        { tarefaId: atual.id, outcome: resultado.outcome },
      );
    }

    const amb = await criarAmbiente(bound);
    const nova = await carregarTarefa(atual.id, bound);
    const tarefa = await montarPendencia(nova, amb, bound);
    const doResponsavel = await listarTodasTarefasPor('responsavelId', pessoa, bound);
    return { tarefa, indicadores: calcularIndicadores(doResponsavel, amb.hoje) };
  });
}

export const requests: {
  [K in keyof InicioContracts]: (
    input: InicioContracts[K]['input'],
    ctx: RequestContext,
  ) => Promise<InicioContracts[K]['output']>;
} = {
  'tarefas.inicio.carregarInicio': async function (_input, ctx) {
    const pessoa = pessoaDaSessao(ctx);
    const amb = await criarAmbiente(ctx);
    const doResponsavel = await listarTodasTarefasPor('responsavelId', pessoa, ctx);
    const doCriador = await listarTodasTarefasPor('criadorId', pessoa, ctx);

    // membroVeResponsavelOuCriador: apenas tarefas de que é responsável ou que criou
    const visiveis = new Map<string, TarefaLida>();
    for (const t of doResponsavel) visiveis.set(t.id, t);
    for (const t of doCriador) visiveis.set(t.id, t);

    // quemAgeAgoraPorSituacao + retomarSoAposDevolucao (devolvidas em andamento já são do responsável)
    const pendentes = Array.from(visiveis.values())
      .filter((t) => derivar(t, amb.hoje).quemAgeAgora === pessoa)
      .sort(comparar);
    const pendencias: PendenciaTarefaOut[] = [];
    for (const t of pendentes) pendencias.push(await montarPendencia(t, amb, ctx));

    // tarefaAbertaVencimento / resumoDiarioOitoHoras: abertas do responsável que vencem hoje ou estão atrasadas
    const paraAlerta = doResponsavel
      .filter((t) => {
        const d = derivar(t, amb.hoje);
        return d.aberta && (d.venceHoje || d.atrasada);
      })
      .sort(comparar);
    const alertas: AlertaPrazoOut[] = [];
    for (const t of paraAlerta) {
      const d = derivar(t, amb.hoje);
      if (d.prazo == null) {
        throw new AppError('INVALID_DATA', 'Tarefa "' + t.titulo + '" em alerta sem prazo', 500, { tarefaId: t.id });
      }
      alertas.push({
        id: t.id,
        titulo: t.titulo,
        prazo: d.prazo,
        status: paraStatus(String(t.status)),
        details: {
          aberta: d.aberta,
          venceHoje: d.venceHoje,
          atrasada: d.atrasada,
          progressoChecklist: await progressoChecklist(t.id, ctx),
        },
      });
    }

    const indicadores = calcularIndicadores(doResponsavel, amb.hoje);

    // participanteNaoConfiguradoAceitaECria: marca do gestor, ou sim quando não configurado
    const participante = await getParticipante({ id: pessoa }, ctx);
    const marcas = participante.details.tarefas;
    const aceita = marcas == null || marcas.aceitaTarefas == null ? true : marcas.aceitaTarefas;
    const podeCriar = marcas == null || marcas.podeCriarTarefas == null ? true : marcas.podeCriarTarefas;

    return {
      pendencias,
      alertas,
      indicadores,
      permissoes: {
        details: {
          identification: { name: participante.details.identification.name },
          tarefas: { aceitaTarefasEfetivo: aceita, podeCriarTarefasEfetivo: podeCriar },
        },
      },
    };
  },

  'tarefas.inicio.iniciarTarefa': async function (input, ctx) {
    return executarTransicao(ctx, {
      id: String(input.id),
      version: Number(input.version),
      transicao: 'iniciar',
      ator: 'responsavel',
      ruleAtor: 'apenasResponsavelExecuta',
      statusEsperado: 'aFazer',
      exigeDevolvida: false,
      exigeMotivo: false,
    });
  },

  'tarefas.inicio.enviarRevisao': async function (input, ctx) {
    return executarTransicao(ctx, {
      id: String(input.id),
      version: Number(input.version),
      transicao: 'enviarParaRevisao',
      ator: 'responsavel',
      ruleAtor: 'apenasResponsavelExecuta',
      statusEsperado: 'emAndamento',
      exigeDevolvida: false,
      exigeMotivo: false,
    });
  },

  'tarefas.inicio.aceitarTarefa': async function (input, ctx) {
    return executarTransicao(ctx, {
      id: String(input.id),
      version: Number(input.version),
      transicao: 'aceitar',
      ator: 'criador',
      ruleAtor: 'apenasCriadorRevisa',
      statusEsperado: 'emRevisao',
      exigeDevolvida: false,
      exigeMotivo: false,
    });
  },

  'tarefas.inicio.devolverTarefa': async function (input, ctx) {
    return executarTransicao(ctx, {
      id: String(input.id),
      version: Number(input.version),
      transicao: 'devolver',
      ator: 'criador',
      ruleAtor: 'apenasCriadorRevisa',
      statusEsperado: 'emRevisao',
      exigeDevolvida: false,
      exigeMotivo: true,
      motivoDevolucao: input.details.motivoDevolucao,
    });
  },

  'tarefas.inicio.retomarTarefa': async function (input, ctx) {
    return executarTransicao(ctx, {
      id: String(input.id),
      version: Number(input.version),
      transicao: 'retomar',
      ator: 'responsavel',
      ruleAtor: 'apenasResponsavelExecuta',
      statusEsperado: 'emAndamento',
      exigeDevolvida: true,
      exigeMotivo: false,
    });
  },
};
